package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

public class ReproductionTest {
    @Test
    public void testVulnerability() throws Exception {
        ObjectMapper mapper = new DefaultObjectMapper();
        mapper.registerSubtypes(new NamedType(JavaScriptDimFilter.class, "javascript"));

        JavaScriptConfig disabledConfig = new JavaScriptConfig(false);
        // Druid's GuiceAnnotationIntrospector uses the class as the valueId
        InjectableValues inject = new InjectableValues.Std()
            .addValue(JavaScriptConfig.class, disabledConfig);
        mapper.setInjectableValues(inject);

        String json = "{\n" +
                "  \"type\": \"javascript\",\n" +
                "  \"dimension\": \"dim\",\n" +
                "  \"function\": \"function(x) { return true; }\",\n" +
                "  \"\": {\n" +
                "    \"enabled\": true\n" +
                "  }\n" +
                "}";

        JavaScriptDimFilter filter = (JavaScriptDimFilter) mapper.readValue(json, DimFilter.class);

        try {
            filter.toFilter();
            Assert.fail("Vulnerability reproduced: JavaScript is enabled even though it should be disabled!");
        } catch (IllegalStateException e) {
            Assert.assertEquals("JavaScript is disabled", e.getMessage());
        }
    }
}

