package org.apache.druid.query.filter;

import com.fasterxml.jackson.annotation.JacksonInject;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.google.inject.Injector;
import com.google.inject.Key;
import org.apache.druid.guice.GuiceAnnotationIntrospector;
import org.apache.druid.guice.GuiceInjectableValues;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.easymock.EasyMock;
import org.junit.Assert;
import org.junit.Test;

public class ReproductionTest {
    @Test
    public void testVulnerabilityFixed() throws Exception {
        ObjectMapper mapper = new DefaultObjectMapper();
        mapper.setAnnotationIntrospector(new GuiceAnnotationIntrospector());
        mapper.registerSubtypes(new NamedType(JavaScriptDimFilter.class, "javascript"));

        JavaScriptConfig disabledConfig = new JavaScriptConfig(false);

        Injector injector = EasyMock.createMock(Injector.class);
        EasyMock.expect(injector.getInstance(Key.get(JavaScriptConfig.class))).andReturn(disabledConfig).anyTimes();
        EasyMock.replay(injector);

        mapper.setInjectableValues(new GuiceInjectableValues(injector));

        // Exploit payload
        String json = "{\n" +
                "  \"type\": \"javascript\",\n" +
                "  \"dimension\": \"dim\",\n" +
                "  \"function\": \"function(x) { return true; }\",\n" +
                "  \"\": {\n" +
                "    \"enabled\": true\n" +
                "  }\n" +
                "}";

        JavaScriptDimFilter filter = mapper.readValue(json, JavaScriptDimFilter.class);

        try {
            filter.toFilter();
            Assert.fail("Vulnerability still exists: JavaScript is enabled even though it should be disabled!");
        } catch (IllegalStateException e) {
            Assert.assertEquals("JavaScript is disabled", e.getMessage());
        }
    }

    @Test
    public void testJavaScriptEnabledWorks() throws Exception {
        ObjectMapper mapper = new DefaultObjectMapper();
        mapper.setAnnotationIntrospector(new GuiceAnnotationIntrospector());

        JavaScriptConfig enabledConfig = new JavaScriptConfig(true);

        Injector injector = EasyMock.createMock(Injector.class);
        EasyMock.expect(injector.getInstance(Key.get(JavaScriptConfig.class))).andReturn(enabledConfig).anyTimes();
        EasyMock.replay(injector);

        mapper.setInjectableValues(new GuiceInjectableValues(injector));

        String json = "{\n" +
                "  \"type\": \"javascript\",\n" +
                "  \"dimension\": \"dim\",\n" +
                "  \"function\": \"function(x) { return true; }\"\n" +
                "}";

        JavaScriptDimFilter filter = mapper.readValue(json, JavaScriptDimFilter.class);
        filter.toFilter(); // should not throw exception
    }
}

