import org.junit.Assert;
import org.junit.Test;

public class ReproductionTest {
    @Test
    public void testVulnerabilityFixed() throws Exception {
        ObjectMapper mapper = new DefaultObjectMapper();
        mapper.setAnnotationIntrospector(new GuiceAnnotationIntrospector());

        JavaScriptConfig disabledConfig = new JavaScriptConfig(false);

        Injector injector = EasyMock.createMock(Injector.class);
        EasyMock.expect(injector.getInstance(Key.get(JavaScriptConfig.class))).andReturn(disabledConfig).anyTimes();
        EasyMock.replay(injector);

        mapper.setInjectableValues(new GuiceInjectableValues(injector));

        // Exploit payload with ""
        String json1 = "{\n" +
                "  \"type\": \"javascript\",\n" +
                "  \"dimension\": \"dim\",\n" +
                "  \"function\": \"function(x) { return true; }\",\n" +
                "  \"\": {\n" +
                "    \"enabled\": true\n" +
                "  }\n" +
                "}";

        JavaScriptDimFilter filter1 = mapper.readValue(json1, JavaScriptDimFilter.class);

        try {
            filter1.toFilter();
            Assert.fail("Vulnerability still exists via \"\"!");
        } catch (IllegalStateException e) {
            Assert.assertEquals("JavaScript is disabled", e.getMessage());
        }

        // Exploit payload with "config"
        String json2 = "{\n" +
                "  \"type\": \"javascript\",\n" +
                "  \"dimension\": \"dim\",\n" +
                "  \"function\": \"function(x) { return true; }\",\n" +
                "  \"config\": {\n" +
                "    \"enabled\": true\n" +
                "  }\n" +
                "}";

        JavaScriptDimFilter filter2 = mapper.readValue(json2, JavaScriptDimFilter.class);

        try {
            filter2.toFilter();
            Assert.fail("Vulnerability still exists via \"config\"!");
        } catch (IllegalStateException e) {
            Assert.assertEquals("JavaScript is disabled", e.getMessage());
        }
    }
}

